index 58eeb11..03e5113 100644
--- a/src/api.ts
+++ b/src/api.ts
@@ -22,7 +22,7 @@ const handlers: Record<string, Record<string, Handler>> = {
     POST(req): ApiResponse {
       const userId = String(req.body?.userId ?? "");
       const problem = userId ? null : "userId is required";
-      if (problem) return { status: 400, body: { error: problem } };
+      if (problem) return { status: 400, body: { error: problem, code: "INVALID_INPUT" } };
       const session = createSession(userId);
       put(sessionId(userId), session);
       return { status: 201, body: { session } };
